  const NUMG = h => h.replace(/\((One|Two|Three|Four|Five|Six)\.\)/g, (m, w) => '<b>' + '¹²³⁴⁵⁶'['One Two Three Four Five Six'.split(' ').indexOf(w)] + ' ____</b>');
  const COLM = '<h4 class="art-h">What’s your favourite TV show? <small>Tell us about a show you love to watch.</small></h4><p><b>Colm Williams</b></p><p><i>Strictly Come Dancing</i> is my family’s favourite TV show! For some people, watching reality TV is <mark>the least interesting</mark> thing to do on a Saturday evening. However, when the new <i>Strictly</i> series begins every autumn, it’s <mark>as important as</mark> Christmas and birthdays in our house! We never miss an episode. We know who’s getting the most votes, who <mark>isn’t as good as</mark> the other contestants, and we usually predict the winner of the competition! <i>Strictly</i> makes weekends special – but watching it on your TV screen is <mark>less exciting</mark> than seeing a live performance. That’s why we’d love to be in the audience in the television studio! We can’t imagine anything better than seeing our favourite dancers on stage!</p>';
